						propreply := &defs.ProposeReplyTS{
							TRUE,
							inst.lb.clientProposals[j].CommandId,
							val,
							inst.lb.clientProposals[j].Timestamp}
						r.ReplyProposeTS(propreply, inst.lb.clientProposals[j].Reply, inst.lb.clientProposals[j].Mutex)
					} else if inst.cmds[j].Op == state.PUT {
						inst.cmds[j].Execute(r.State)
					}
				}
				executed = true
				r.executedUpTo++
			} else {
				if i == problemInstance {
					timeout += SLEEP_TIME_NS
					if timeout >= COMMIT_GRACE_PERIOD {
						for k := problemInstance; k <= r.crtInstance; k++ {
							r.instancesToRecover <- k
						}
						problemInstance = 0
						timeout = 0
					}
				} else {
					problemInstance = i
					timeout = 0
				}
				break
			}
		}

		if !executed {
			r.M.Lock()
			r.M.Unlock() // FIXME for cache coherence
			time.Sleep(SLEEP_TIME_NS)
		}
	}
}

func (c *Client) Disconnect() {
	for _, s := range c.servers {
		if s != nil {
			s.Close()
		}
	}
	if c.master != nil {
		c.master.Close()
		c.master = nil
	}
}

func (c *Client) Reconnect() error {
	c.Println("dialing master...")
	_, err := c.dialMaster()
	if err != nil {
		return err
	}

	if !c.Leaderless {
		c.Println("getting leader from master...")
		gl, err := c.callMaster("GetLeader")
		if err != nil {
			return err
		}
		masterReply := gl.(*defs.GetLeaderReply)
		c.LeaderId = masterReply.LeaderId
		c.Println("leader id", c.LeaderId)
	}

	return nil
}

func (c *Client) SendProposal(cmd defs.Propose) {
	d := c.LeaderId
	if c.Leaderless {
		d = c.ClosestId
	}

	if !c.Fast {
		c.Println("sending command", cmd.CommandId, "to", d)
		c.writers[d].WriteByte(defs.PROPOSE)
		cmd.Marshal(c.writers[d])
		c.writers[d].Flush()
	} else {
		c.Println("sending command", cmd.CommandId, "to everyone")
		for rep := 0; rep < len(c.servers); rep++ {
			if c.writers[rep] != nil {
				c.writers[rep].WriteByte(defs.PROPOSE)
				cmd.Marshal(c.writers[rep])
				c.writers[rep].Flush()
			}
		}
	}
}

func (c *Client) SendWrite(key int64, value []byte) int32 {
	c.seqnum++
	p := defs.Propose{
		CommandId: c.seqnum,
		ClientId:  c.ClientId,
		Command: state.Command{
			Op: state.PUT,
			K:  state.Key(key),
			V:  value,
		},
		Timestamp: 0,
	}

	c.SendProposal(p)
	return c.seqnum
}

func (c *Client) SendRead(key int64) int32 {
	c.seqnum++
	p := defs.Propose{
		CommandId: c.seqnum,
		ClientId:  c.ClientId,
		Command: state.Command{
			Op: state.GET,
			K:  state.Key(key),
			V:  state.NIL(),
		},
		Timestamp: 0,
	}

	c.SendProposal(p)
	return c.seqnum
}

func (c *Client) SendScan(key, count int64) int32 {
	c.seqnum++
	p := defs.Propose{
		CommandId: c.seqnum,
		ClientId:  c.ClientId,
		Command: state.Command{
			Op: state.SCAN,
			K:  state.Key(key),
			V:  make([]byte, 8),
		},
		Timestamp: 0,
	}

	binary.LittleEndian.PutUint64(p.Command.V, uint64(count))

	c.SendProposal(p)
	return c.seqnum
}

func (c *Client) GetReplyFrom(rid int) (*defs.ProposeReplyTS, error) {
	rep := &defs.ProposeReplyTS{}
	err := rep.Unmarshal(c.readers[rid])
	return rep, err
}

func (c *Client) RegisterRPCTable(t *fastrpc.Table) {

type Replica struct {
	*replica.Replica
	prepareChan           chan fastrpc.Serializable
	acceptChan            chan fastrpc.Serializable
	commitChan            chan fastrpc.Serializable
	commitShortChan       chan fastrpc.Serializable
	prepareReplyChan      chan fastrpc.Serializable
	acceptReplyChan       chan fastrpc.Serializable
	instancesToRecover    chan int32
	prepareRPC            uint8
	acceptRPC             uint8
	commitRPC             uint8
	commitShortRPC        uint8
	prepareReplyRPC       uint8
	acceptReplyRPC        uint8
	IsLeader              bool
	instanceSpace         []*Instance
	crtInstance           int32
	maxRecvBallot         int32
	defaultBallot         []int32
	smallestDefaultBallot int32
	Shutdown              bool
	counter               int
	flush                 bool
	executedUpTo          int32
	batchWait             int

	totalRecNum  int
	totalSendNum int
}

type InstanceStatus int

const (
	PREPARING InstanceStatus = iota
	PREPARED
	ACCEPTED
	COMMITTED
)

type Instance struct {
	cmds   []state.Command
	bal    int32
	vbal   int32
	status InstanceStatus
	lb     *LeaderBookkeeping
}

type LeaderBookkeeping struct {
	clientProposals []*defs.GPropose
	prepareOKs      int
	acceptOKs       int
	nacks           int
	ballot          int32
	cmds            []state.Command
	lastTriedBallot int32
}

func New(alias string, id int, addrs []string, isLeader bool, f int, conf *config.Config, logger *dlog.Logger) *Replica {
	r := &Replica{
		Replica: replica.New(alias, id, f, addrs, false, true, false, conf, logger),

		prepareChan:      make(chan fastrpc.Serializable, defs.CHAN_BUFFER_SIZE),
		acceptChan:       make(chan fastrpc.Serializable, defs.CHAN_BUFFER_SIZE),
		commitChan:       make(chan fastrpc.Serializable, defs.CHAN_BUFFER_SIZE),
		commitShortChan:  make(chan fastrpc.Serializable, defs.CHAN_BUFFER_SIZE),
		prepareReplyChan: make(chan fastrpc.Serializable, defs.CHAN_BUFFER_SIZE),
		acceptReplyChan:  make(chan fastrpc.Serializable, 3*defs.CHAN_BUFFER_SIZE),

		instancesToRecover: make(chan int32, 3*defs.CHAN_BUFFER_SIZE),
		instanceSpace:      make([]*Instance, 15*1024*1024),

		crtInstance:   -1,
		maxRecvBallot: -1,
		defaultBallot: make([]int32, len(addrs)),

		smallestDefaultBallot: -1,

		IsLeader: isLeader,

		flush:        true,
		executedUpTo: -1,
	}

	for i := 0; i < len(r.defaultBallot); i++ {
		r.defaultBallot[i] = -1
	}

	r.prepareRPC = r.RPC.Register(new(Prepare), r.prepareChan)
	r.acceptRPC = r.RPC.Register(new(Accept), r.acceptChan)
	r.commitRPC = r.RPC.Register(new(Commit), r.commitChan)
	r.commitShortRPC = r.RPC.Register(new(CommitShort), r.commitShortChan)
	r.prepareReplyRPC = r.RPC.Register(new(PrepareReply), r.prepareReplyChan)
	r.acceptReplyRPC = r.RPC.Register(new(AcceptReply), r.acceptReplyChan)

	go r.run()

	return r
}

func (r *Replica) recordInstanceMetadata(inst *Instance) {
	if !r.Durable {
		return
	}

	var b [5]byte
	binary.LittleEndian.PutUint32(b[0:4], uint32(inst.bal))
	b[4] = byte(inst.status)
	r.StableStore.Write(b[:])
}

func (r *Replica) recordCommands(cmds []state.Command) {
	if !r.Durable {
		return
	}

	if cmds == nil {
		return
	}
	for i := 0; i < len(cmds); i++ {
		cmds[i].Marshal(io.Writer(r.StableStore))
	}
}

func (r *Replica) sync() {
	if !r.Durable {
		return
	}

	r.StableStore.Sync()
}

