func (r *Replica) bcastAccept(instance int32) {
	defer func() {
		if err := recover(); err != nil {
			r.Println("Accept bcast failed:", err)
		}
	}()
	pa.LeaderId = r.Id
	pa.Instance = instance
	pa.Ballot = r.instanceSpace[instance].lb.lastTriedBallot
	pa.Command = r.instanceSpace[instance].lb.cmds
	args := &pa

	n := r.N - 1

	sent := 0
	for q := 0; q < r.N-1; q++ {
		if !r.Alive[r.PreferredPeerOrder[q]] {
			continue
		}
		r.SendMsg(r.PreferredPeerOrder[q], r.acceptRPC, args)
		sent++
		if sent >= n {
			break
		}
	}

}

var pc Commit
var pcs CommitShort

func (r *Replica) bcastCommit(instance int32, ballot int32, command []state.Command) {
	defer func() {
		if err := recover(); err != nil {
			r.Println("Commit bcast failed:", err)
		}
	}()
	pc.LeaderId = r.Id
	pc.Instance = instance
	pc.Ballot = ballot
	pc.Command = command

	pcs.LeaderId = r.Id
	pcs.Instance = instance
	pcs.Ballot = ballot
	pcs.Count = int32(len(command))
	args := &pc

	sent := 0
	for q := 0; q < r.N-1; q++ {
		if !r.Alive[r.PreferredPeerOrder[q]] {
			continue
		}
		r.SendMsg(r.PreferredPeerOrder[q], r.commitShortRPC, args)
		sent++
	}

}

func (r *Replica) handlePropose(propose *defs.GPropose) {
	if !r.IsLeader {
		preply := &defs.ProposeReplyTS{FALSE, -1, state.NIL(), 0}
		r.ReplyProposeTS(preply, propose.Reply, propose.Mutex)
		return
	}

	batchSize := len(r.ProposeChan) + 1

	proposals := make([]*defs.GPropose, batchSize)
	cmds := make([]state.Command, batchSize)
	proposals[0] = propose
	cmds[0] = propose.Command
	for i := 1; i < batchSize; i++ {
		prop := <-r.ProposeChan
		proposals[i] = prop
		cmds[i] = prop.Command
	}

	r.crtInstance++
	r.instanceSpace[r.crtInstance] = &Instance{
		nil,
		r.defaultBallot[r.Id],
		r.defaultBallot[r.Id],
		PREPARING,
		&LeaderBookkeeping{proposals, 0, 0, 0, r.Id, nil, -1}}
	r.makeBallot(r.crtInstance)

	inst := r.instanceSpace[r.crtInstance]
	lb := inst.lb
	r.defaultBallot[r.Id] = lb.lastTriedBallot

	if lb.lastTriedBallot != r.smallestDefaultBallot {
		r.bcastPrepare(r.crtInstance)
	} else {
		inst.cmds = cmds
		inst.lb.cmds = cmds
		inst.bal = lb.lastTriedBallot
		inst.vbal = lb.lastTriedBallot
		inst.status = ACCEPTED
		r.bcastAccept(r.crtInstance)
	}
}

		State:       state.InitState(),
		RPC:         fastrpc.NewTableId(defs.RPC_TABLE),
		StableStore: nil,
		Stats:       &defs.Stats{make(map[string]int)},
		Shutdown:    false,
		Listener:    nil,
		ProposeChan: make(chan *defs.GPropose, defs.CHAN_BUFFER_SIZE),
		BeaconChan:  make(chan *defs.GBeacon, defs.CHAN_BUFFER_SIZE),

		Thrifty: thrifty,
		Exec:    exec,
		LRead:   lread,
		Dreply:  true,
		Beacon:  false,
		Durable: false,

		Ewma:      make([]float64, n),
		Latencies: make([]int64, n),

		Dt: defs.NewLatencyTable(defs.LatencyConf, defs.IP(), addrs),
	}

	for i := 0; i < r.N; i++ {
		r.PreferredPeerOrder[i] = int32((int(r.Id) + 1 + i) % r.N)
		r.Ewma[i] = 0.0
		r.Latencies[i] = 0
	}

	return r
}

